using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
public static class ProjectMapTrafficSessionTests {
 [Serializable] sealed class DraftFixture {public string fingerprint,trafficJson;public ProjectMapObject[] objects;}
 static void Check(bool ok,string message){if(!ok)throw new Exception("TRAFFIC_SESSION_FAIL "+message);}
 public static void Run(){
  string source=ProjectMapStore.FindRoot(Application.dataPath),root=Path.Combine(source,"artifacts/traffic-session-"+Guid.NewGuid().ToString("N"));
  Directory.CreateDirectory(Path.Combine(root,".git"));Directory.CreateDirectory(Path.Combine(root,"unity/EungyeTaxi/ProjectSettings"));File.WriteAllText(Path.Combine(root,"unity/EungyeTaxi/ProjectSettings/ProjectVersion.txt"),"fixture");Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(root,ProjectMapStore.RelativePath)));File.Copy(ProjectMapStore.SourcePath(source),Path.Combine(root,ProjectMapStore.RelativePath));
  var session=ProjectMapEditSession.Open(root);
  try{
   Check(session.Traffic.scene==null,"borrowed traffic excludes scene");var borrowed=session.Traffic;Check(ReferenceEquals(borrowed,session.Traffic),"repaint read has no copies");string initial=borrowed.ToJson();int notifications=0;session.TrafficChanged+=()=>notifications++;
   bool rejected=false;try{session.EditTraffic(d=>{d.lanes[0].width=float.NaN;});}catch(ArgumentException){rejected=true;}Check(rejected&&!session.Dirty&&session.Traffic.ToJson()==initial,"invalid transaction rolls back");
   try{session.EditTraffic(d=>{d.lanes[0].width=4;throw new InvalidOperationException();});}catch(InvalidOperationException){}Check(!session.Dirty&&session.Traffic.ToJson()==initial,"throwing callback rolls back");
   Action fail=()=>{throw new InvalidOperationException();};session.TrafficChanged+=fail;try{session.EditTraffic(d=>d.lanes[0].roadName="rollback");}catch(InvalidOperationException){}session.TrafficChanged-=fail;Check(!session.Dirty&&session.Traffic.ToJson()==initial,"listener failure rolls back");Undo.IncrementCurrentGroup();
   string laneId=session.Traffic.lanes[0].id;int turn=session.Traffic.lanes[0].turn==0?1:0;string junction=session.Baseline.junctionRules.First().id;
   session.EditTraffic(d=>{d.lanes[0].turn=turn;d.facilities=d.facilities.Concat(new[]{new RoadMapFacility{id="test:facility",x=10,z=10,text="session roundtrip"}}).ToArray();var signal=d.signals.FirstOrDefault(s=>s.junctionId==junction);if(signal==null)d.signals=d.signals.Concat(new[]{new RoadMapSignalProgram{junctionId=junction,groups=new[]{new RoadMapSignalGroup{id="test:group"}},stages=new[]{new RoadMapStage{groups=new[]{"test:group"}}}}}).ToArray();else signal.stages[0].green+=1;});
   string edited=session.Traffic.ToJson();Undo.FlushUndoRecordObjects();Undo.PerformUndo();Check(!session.Dirty&&session.Traffic.ToJson()==initial,"traffic undo restores exact clean document");Undo.PerformRedo();Check(session.Dirty&&session.Traffic.ToJson()==edited&&notifications>=3,"traffic redo and notifications");
   var building=session.Objects.First(o=>o.enabled&&o.kind=="building");session.Transform(building.id,Vector3.zero,0,Vector2.one,1.01f);string created=session.CreateObject("land",new Vector3(10,0,10));session.AddVertex(created,0);Check(session.GetObject(created).points.Length==5,"insert vertex");session.DeleteVertex(created,1);Check(session.GetObject(created).points.Length==4,"delete vertex");Undo.FlushUndoRecordObjects();Undo.IncrementCurrentGroup();session.DeleteObject(created);Check(!session.GetObject(created).enabled,"delete tombstone");Undo.FlushUndoRecordObjects();Undo.PerformUndo();Check(session.GetObject(created).enabled,"delete undo");
   session.WriteDraft();session.Dispose();session=ProjectMapEditSession.Open(root);
   string validDraft=File.ReadAllText(session.DraftPath),cleanDocument=session.Document.ToJson();int cleanHandles=session.EditedHandleCount;var malformed=JsonUtility.FromJson<DraftFixture>(validDraft);malformed.objects=malformed.objects.Concat(new[]{new ProjectMapObject{id="native:late-malformed",kind="land",width=-1,points=ProjectMapScene.Rectangle(new Vector3(10,0,10),Vector3.forward,6,6)}}).ToArray();string malformedBytes=JsonUtility.ToJson(malformed);File.WriteAllText(session.DraftPath,malformedBytes);rejected=false;try{session.RecoverDraft();}catch(IOException){rejected=true;}Check(rejected&&!session.Dirty&&session.EditedHandleCount==cleanHandles&&session.Document.ToJson()==cleanDocument&&File.ReadAllText(session.DraftPath)==malformedBytes,"late malformed draft object leaves exact clean state and bytes");File.WriteAllText(session.DraftPath,validDraft);
   Action<string[]> failRecovery=ids=>{throw new InvalidOperationException("draft notification failure");};session.Changed+=failRecovery;rejected=false;try{session.RecoverDraft();}catch(InvalidOperationException){rejected=true;}session.Changed-=failRecovery;Check(rejected&&!session.Dirty&&session.EditedHandleCount==cleanHandles&&session.Document.ToJson()==cleanDocument&&File.ReadAllText(session.DraftPath)==validDraft,"failed recovery notification rolls back complete draft and handle set");
   session.RecoverDraft();Check(session.Traffic.ToJson()==edited&&session.GetObject(created).enabled&&session.GetObject(building.id).height>building.height,"combined draft recovery");
   var snapshot=session.Document;snapshot.lanes[0].roadName="detached";Check(session.Traffic.lanes[0].roadName!="detached","full document snapshot detached");string beforeImport=session.Document.ToJson();var invalid=session.Document;invalid.baseHash="different baseline";rejected=false;try{session.ImportDocument(invalid);}catch(Exception){rejected=true;}Check(rejected&&session.Document.ToJson()==beforeImport,"invalid native import is atomic");
   var imported=session.Document;var added=JsonUtility.FromJson<ProjectMapObject>(JsonUtility.ToJson(session.GetObject(created)));added.id="native:stable-import";imported.scene.objects=imported.scene.objects.Where(o=>o.id!=created).Concat(new[]{added}).ToArray();imported.lanes[0].roadName="native imported lane";
   Action<string[]> badImport=ids=>{throw new InvalidOperationException("import listener");};session.Changed+=badImport;rejected=false;try{session.ImportDocument(imported);}catch(InvalidOperationException){rejected=true;}session.Changed-=badImport;Check(rejected&&session.Document.ToJson()==beforeImport&&!session.ObjectIds.Contains(added.id),"listener failure rolls back entire import");
   session.ImportDocument(imported);Check(session.GetObject(added.id).enabled&&!session.GetObject(created).enabled&&session.Traffic.lanes[0].roadName=="native imported lane","native import keeps stable IDs and disables removed objects");Undo.FlushUndoRecordObjects();Undo.PerformUndo();Check(!session.GetObject(added.id).enabled&&session.GetObject(created).enabled&&session.Traffic.ToJson()==edited,"native import undo is one transaction");Undo.PerformRedo();Check(session.GetObject(added.id).enabled&&!session.GetObject(created).enabled,"native import redo");
   session.WriteDraft();session.Dispose();session=ProjectMapEditSession.Open(root);session.RecoverDraft();Check(session.GetObject(added.id).enabled&&session.Traffic.lanes[0].roadName=="native imported lane","native stable ID draft recovery");
   var composed=session.Compose();Check(composed.hdEdges.First(e=>e.id==laneId).turn==turn,"compose applies traffic");session.Save();Check(!session.Dirty&&!session.HasDraft,"combined save cleans draft");var savedObject=session.GetObject("native:stable-import");session.EditTraffic(d=>d.lanes[0].roadName="unsaved after save");session.DeleteObject(savedObject.id);session.RestoreAll();Check(!session.Dirty&&session.GetObject(savedObject.id).enabled&&session.Traffic.lanes[0].roadName=="native imported lane","restore uses last successful save including traffic and newly saved objects");session.Dispose();session=ProjectMapEditSession.Open(root);Check(session.Traffic.lanes.First(l=>l.id==laneId).turn==turn&&session.Traffic.facilities.Any(f=>f.id=="test:facility")&&session.Traffic.signals.Any(s=>s.junctionId==junction)&&session.GetObject("native:stable-import").enabled&&(!session.ObjectIds.Contains(created)||!session.GetObject(created).enabled),"save reload retains traffic and objects; unsaved removed tombstone may be absent");
   Directory.CreateDirectory(Path.GetDirectoryName(session.DraftPath));File.WriteAllText(session.DraftPath,"{}");session.EditTraffic(d=>d.lanes[0].roadName="draft persistence failure");rejected=false;try{session.Dispose();}catch(IOException){rejected=true;}Check(rejected&&session.Dirty&&session.Traffic.lanes[0].roadName=="draft persistence failure","failed dispose retains live session for recovery");session.DiscardDraft();session.RestoreAll();Check(!session.Dirty,"retry after resolving draft conflict remains usable");
   Debug.Log("PROJECT_MAP_TRAFFIC_SESSION_TESTS_OK");
  }finally{session.Dispose();}
 }
}
